// PLAZAS-TESTIGO. Las 230 ciudades disputadas que la ronda 20 uso para
// sondear el mapa, con la cronologia real que sus agentes documentaron.
// Vive aqui, en tools/, y no en un directorio de trabajo, porque dos
// herramientas la necesitan -plazas.js como lista de sondeo y rotulos.js como
// gazetteer- y en la Mac no existe /tmp/v20: alli el auditor de rotulos se
// quedaba con 246 lugares en vez de 416 y perdia la mitad de sus avisos, sin
// decir nada. Una herramienta que depende de un fichero temporal no es una
// herramienta, es un apunte.
