  "razon": "Yazd y Abarquh son el feudo que los selyucidas dan a Faramurz tras rendir Isfahan en 1051, y donde los kakuyies siguen gobernando -construyendo mezquitas, canales y fortificaciones- hasta la muerte de Garshasp II en la batalla de Qatwan (1141). Es el unico sondeo que mide los noventa anos finales de la dinastia; sin el, `kakuyid` solo estaria medida por Rayy 1040 e Isfahan. El ano 1250 va sin expectativa a proposito: entre 1141 y los ilkhanes mandan los atabegs de Yazd, que el mapa no tiene, y el punto sale VACIO -un hueco anterior a este lote, no abierto por el-."
