  "razon": "Aix es la residencia de los condes desde Ramon Berenguer I y la capital administrativa del condado angevino, asi que mide `provenza` desde el primer ano del arco: a diferencia de Marsella, que fue comuna en rebeldia hasta 1252-1257, en 1250 Aix ya estaba bajo autoridad condal. Carlos III lega el condado a Luis XI el 10 de diciembre de 1481 y Carlos VIII proclama la union en octubre de 1486; el mapa hace la bisagra en 1481. Los anios 1100 y 1200 van sin expectativa: el condado de la casa de Barcelona (1112-1245) tampoco era Imperio, pero este lote no lo modela y esta declarado en el informe."
