  "razon": "Yutian, el oasis del rio Keriya, extremo ORIENTAL del reino de Jotan por la ruta del sur: el Hou Hanshu dice que bajo el rey Guangde (h. 61) le obedecian trece reinos \"desde Jingjue (Niya) al noroeste hasta Kashgar\". Mide el borde este de `khotan`, que el de Jotan capital no distingue. 700 y 800 van SIN expectativa a proposito: el reino era entonces guarnicion Tang (Pisha, una de las Cuatro de Anxi) y luego tibetano, pero los anillos de `tang` y de `tibetan_empire` no llegan tan al sureste y el mapa devuelve `tarim_pueblos`; queda anotado como defecto de cobertura ajeno a este lote, no como expectativa insatisfacible. 1600 tampoco lleva expectativa: es el hueco entre el kanato de Yarkand y la conquista dzungara, que el mapa resuelve con sustrato."
