  "razon": "Yecheng/Karghalik, extremo OCCIDENTAL del reino, entre Jotan y Yarkanda, es la plaza que mide la guerra karajanida: el par 998/1010 dice si el mapa distingue el Jotan independiente del Jotan conquistado. 1000 y 1005 van SIN expectativa deliberadamente: el frente de la guerra de 1000-1006 no lo fija ninguna fuente ano por ano -la Iranica solo dice que la conquista se completa \"antes de 407/1016-17\" y que las monedas de Yusuf Qadir Kan acunadas en Jotan son de 1016-17-, y afirmar quien tenia Karghalik en un ano concreto de esa guerra seria inventar precision. Lo que el mapa devuelve ahi (karajanida) es defendible y lo que devolveria `khotan` tambien; por eso se sondea y no se juzga."
