  "razon": "El valle del Ili, la mitad oriental de Semirechye, es la parte del kanato turgues que Suyab y Talas no miden: las dos estan en el Chu y en el Talas, al oeste. La serie sigue la cadena de dominadores del Zhetysu: kanato turco (552), kanato turco occidental (581-657), protectorado Tang nominal, turgueses (699-766, aqui hasta 748), carlucos (766), karajanidas, kara-kitai y mongoles. 660 va SIN expectativa por la misma razon que el 660 de Suyab: el protectorado Tang de esos anios era nominal y el testigo de Suyab ya lo dejo en blanco; mantener el mismo criterio en las dos plazas es mas util que forzar una respuesta."
