  "razon": "Kazerun, en el Fars interior entre Shiraz y el golfo, mide el cuerpo del emirato inyuida y no solo su capital. El par 1330/1340 fecha la independencia (los Inyu administraban el inyu, la tierra de la corona ilkani, desde 1304; se hacen autonomos al morir Abu Said en 1335) y el par 1352/1360 la conquista muzafari (invasion de Fars en 1352, caida de Shiraz en 1353). 1400 y 1470 siguen la cadena posterior, identica a la de Shiraz, para que las dos plazas se contrasten."
